using System;using System.Data;using System.Linq;using System.Text;using System.Web;using System.Web.UI;using Newtonsoft.Json;namespace AQOONHUB_SMS.Modules.Administration{public partial class LoginActivityPage:Page{readonly SystemRepository r=new SystemRepository();int P{get{return Math.Max(1,(int?)(ViewState["P"])??1);}set{ViewState["P"]=Math.Max(1,value);}}int Pages{get{return Math.Max(1,(int?)(ViewState["Pages"])??1);}set{ViewState["Pages"]=value;}}protected void Page_Load(object s,EventArgs e){SystemAuthorization.DemandSecurity(this);if(!IsPostBack){ddlRole.Items.Add(new System.Web.UI.WebControls.ListItem("All roles",""));foreach(DataRow x in r.Roles().Rows)ddlRole.Items.Add(x["RoleName"].ToString());txtFrom.Text=DateTime.Today.AddDays(-6).ToString("yyyy-MM-dd");txtTo.Text=DateTime.Today.ToString("yyyy-MM-dd");Bind();}}DateTime? D(string x){DateTime d;return DateTime.TryParse(x,out d)?d:(DateTime?)null;}void Dates(){if(D(txtFrom.Text).HasValue&&D(txtTo.Text).HasValue&&D(txtFrom.Text)>D(txtTo.Text))throw new InvalidOperationException("From date must not be after To date.");}void Bind(){try{Dates();int z=int.Parse(ddlPageSize.SelectedValue);PagedData p=r.LoginPage(D(txtFrom.Text),D(txtTo.Text),ddlRole.SelectedValue,ddlStatus.SelectedValue,txtSearch.Text.Trim(),P,z);Pages=Math.Max(1,(int)Math.Ceiling(p.Total/(double)z));if(P>Pages){P=Pages;Bind();return;}gv.DataSource=p.Rows;gv.DataBind();DataTable all=r.Login(D(txtFrom.Text),D(txtTo.Text),ddlRole.SelectedValue,ddlStatus.SelectedValue,txtSearch.Text.Trim());litSuccess.Text=all.Select("Status='Success'").Length.ToString();litFailed.Text=(all.Rows.Count-all.Select("Status='Success'").Length).ToString();litPage.Text="Page "+P+" of "+Pages+" · "+p.Total+" records";pgFirst.Enabled=pgPrev.Enabled=P>1;pgNext.Enabled=pgLast.Enabled=P<Pages;DateTime f=D(txtFrom.Text)??DateTime.Today.AddDays(-6),to=D(txtTo.Text)??DateTime.Today;var q=r.LoginTrend(f,to).AsEnumerable();chartLabels.Value=JsonConvert.SerializeObject(q.Select(x=>Convert.ToDateTime(x["D"]).ToString("dd MMM")));chartSuccess.Value=JsonConvert.SerializeObject(q.Select(x=>Convert.ToInt32(x["SuccessCount"])));chartFailed.Value=JsonConvert.SerializeObject(q.Select(x=>Convert.ToInt32(x["FailedCount"])));}catch(Exception ex){Error(ex.Message);}}protected void btnFilter_Click(object s,EventArgs e){P=1;Bind();}protected void btnReset_Click(object s,EventArgs e){txtFrom.Text=DateTime.Today.AddDays(-6).ToString("yyyy-MM-dd");txtTo.Text=DateTime.Today.ToString("yyyy-MM-dd");txtSearch.Text="";ddlRole.SelectedIndex=ddlStatus.SelectedIndex=0;P=1;Bind();}protected void PageSizeChanged(object s,EventArgs e){P=1;Bind();}protected void PageNav(object s,EventArgs e){string id=((Control)s).ID;P=id=="pgFirst"?1:id=="pgPrev"?P-1:id=="pgNext"?P+1:Pages;Bind();}protected void gv_RowCommand(object s,System.Web.UI.WebControls.GridViewCommandEventArgs e){long id;if(e.CommandName!="Details"||!long.TryParse(Convert.ToString(e.CommandArgument),out id))return;DataRow x=r.LoginDetail(id);if(x==null){Error("Login activity not found.");return;}litDetails.Text=F("User",x["UserName"])+F("Role",x["Role"])+F("Login Time",x["LoginTime"])+F("Status",x["Status"])+F("Failure Reason",x["FailureReason"])+F("IP Address",x["IPAddress"])+F("Device / Browser",x["DeviceInfo"])+F("User Agent","Unavailable")+F("Logout Time","Unavailable")+F("Session Duration","Unavailable");pnlDetails.Visible=true;}protected void CloseDetails(object s,EventArgs e){pnlDetails.Visible=false;}protected void btnExport_Click(object s,EventArgs e){Dates();DataTable t=r.Login(D(txtFrom.Text),D(txtTo.Text),ddlRole.SelectedValue,ddlStatus.SelectedValue,txtSearch.Text.Trim());var b=new StringBuilder("\uFEFFUser,Email,Role,Login Time,Device,IP Address,Status,Failure Reason\r\n");foreach(DataRow x in t.Rows)b.AppendLine(C(x["UserName"])+","+C(x["Email"])+","+C(x["Role"])+","+C(x["LoginTime"])+","+C(x["DeviceInfo"])+","+C(x["IPAddress"])+","+C(x["Status"])+","+C(x["FailureReason"]));Response.Clear();Response.ContentType="text/csv";Response.AddHeader("Content-Disposition","attachment; filename=login-activity-"+DateTime.Now.ToString("yyyyMMdd-HHmm")+".csv");Response.BinaryWrite(Encoding.UTF8.GetBytes(b.ToString()));Response.End();}string C(object o){string v=Convert.ToString(o);if(v.Length>0&&"=+-@".Contains(v.Substring(0,1)))v="'"+v;return "\""+v.Replace("\"","\"\"")+"\"";}string F(string k,object v){string z=string.IsNullOrWhiteSpace(Convert.ToString(v))?"Unavailable":Convert.ToString(v);return "<div><dt>"+HttpUtility.HtmlEncode(k)+"</dt><dd>"+HttpUtility.HtmlEncode(z)+"</dd></div>";}void Error(string m){litMessage.Text="<div class='sys-error' role='alert'>"+HttpUtility.HtmlEncode(m)+"</div>";}}
}
